{"path": "workflow.py", "content": "import csv
import io
import json
from decimal import Decimal, InvalidOperation
from collections import OrderedDict


def _parse_amount(s):
    """Parse a decimal string into cents (int). Reject NaN, Infinity, negatives, >2 decimal places."""
    s = s.strip()
    if not s:
        raise ValueError("Empty amount")
    # Reject NaN and Infinity variants
    lower = s.lower()
    if lower in ('nan', 'inf', '+inf', '-inf', 'infinity', '+infinity', '-infinity'):
        raise ValueError(f"Invalid amount: {s}")
    try:
        d = Decimal(s)
    except InvalidOperation:
        raise ValueError(f"Invalid amount: {s}")
    if d.is_nan() or d.is_infinite():
        raise ValueError(f"Invalid amount: {s}")
    if d < 0:
        raise ValueError(f"Negative amount: {s}")
    # Check at most 2 decimal places
    # Quantize to 2 places and compare
    quantized = d.quantize(Decimal('0.01'))
    if d != quantized:
        raise ValueError(f"More than 2 decimal places: {s}")
    # Convert to cents as integer
    cents = int(d * 100)
    return cents


def _read_csv(text):
    """Read CSV text into list of dicts. Returns empty list if no rows (header only or empty)."""
    if not text or not text.strip():
        return []
    reader = csv.DictReader(io.StringIO(text))
    rows = []
    for row in reader:
        rows.append(row)
    return rows


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """Reconcile orders and refunds per v1 contract."""
    orders_rows = _read_csv(orders_csv)
    refunds_rows = _read_csv(refunds_csv)

    # --- Process orders ---
    # Deduplicate by order_id
    orders_map = {}  # order_id -> row dict
    for row in orders_rows:
        oid = row.get('order_id', '').strip()
        if oid in orders_map:
            existing = orders_map[oid]
            # Check if all fields are identical
            if existing != row:
                raise ValueError(f"Duplicate order_id {oid} with different fields")
            # Identical row, skip
            continue
        orders_map[oid] = row

    # Filter to paid orders only
    paid_orders = {}
    for oid, row in orders_map.items():
        status = row.get('status', '').strip()
        if status == 'paid':
            paid_orders[oid] = row

    # Build order results
    order_results = []
    for oid in sorted(paid_orders.keys()):
        row = paid_orders[oid]
        customer = row.get('customer', '').strip()
        amount_str = row.get('amount', '').strip()
        paid_cents = _parse_amount(amount_str)
        order_results.append({
            'order_id': oid,
            'customer': customer,
            'paid_cents': paid_cents,
            'refund_cents': 0,
            'net_cents': paid_cents
        })

    # --- Process refunds ---
    # Deduplicate by refund_id
    refunds_map = {}  # refund_id -> row dict
    for row in refunds_rows:
        rid = row.get('refund_id', '').strip()
        if rid in refunds_map:
            existing = refunds_map[rid]
            if existing != row:
                raise ValueError(f"Duplicate refund_id {rid} with different fields")
            continue
        refunds_map[rid] = row

    # Apply refunds to orders
    refund_by_order = {}  # order_id -> total refund cents
    for rid, row in refunds_map.items():
        oid = row.get('order_id', '').strip()
        amount_str = row.get('amount', '').strip()
        refund_cents = _parse_amount(amount_str)

        # Validate: order must exist and be paid
        if oid not in paid_orders:
            raise ValueError(f"Refund {rid} references unknown or non-paid order {oid}")

        if oid not in refund_by_order:
            refund_by_order[oid] = 0
        refund_by_order[oid] += refund_cents

    # Check cumulative refund does not exceed paid
    for oid, total_refund in refund_by_order.items():
        row = paid_orders[oid]
        paid_cents = _parse_amount(row.get('amount', '').strip())
        if total_refund > paid_cents:
            raise ValueError(f"Refund for order {oid} exceeds paid amount")

    # Update order results with refund info
    for order in order_results:
        oid = order['order_id']
        if oid in refund_by_order:
            order['refund_cents'] = refund_by_order[oid]
            order['net_cents'] = order['paid_cents'] - order['refund_cents']

    # --- Customer summary ---
    customer_map = {}  # customer -> net_cents
    for order in order_results:
        cust = order['customer']
        if cust not in customer_map:
            customer_map[cust] = 0
        customer_map[cust] += order['net_cents']

    customers = []
    for cust in sorted(customer_map.keys()):
        customers.append({
            'customer': cust,
            'net_cents': customer_map[cust]
        })

    # --- Totals ---
    total_paid = sum(o['paid_cents'] for o in order_results)
    total_refund = sum(o['refund_cents'] for o in order_results)
    total_net = total_paid - total_refund

    return {
        'orders': order_results,
        'customers': customers,
        'totals': {
            'paid_cents': total_paid,
            'refund_cents': total_refund,
            'net_cents': total_net
        }
    }


def export_bundle(result):
    return {"summary.json": "{}"}
